const REPOSITORY_ROOT = resolve(import.meta.dirname, '..')

/** Strict type-aware override globs = .oxlintrc.json overrides[0].files. A file
 *  matching any of these MUST be claimed by a real tsconfig program; falling
 *  into tsgolint's option-less inferred program is silent type-aware under-check
 *  (UM-LINT-B). Pinned by scripts/oxlint-contract.spec.ts (contract test asserts
 *  this equals .oxlintrc.json overrides[0].files, catching drift at test time). */
const STRICT_OVERRIDE_GLOBS = [
  'packages/*/*/src/**/*.{ts,tsx}',
  'packages/*/*/tests/**/*.{ts,tsx}',
  'apps/*/src/**/*.{ts,tsx}',
  'apps/*/tests/**/*.{ts,tsx}',
  'examples/**/*.{ts,tsx}',
  'scripts/**/*.{ts,tsx}',
  'website/**/*.{ts,tsx}',
] as const

/** Temporary allowlist pending the eval-team-coordinated tsconfig.tests.json FIX
 *  (UM-LINT-B Bucket i sub-option b). Remove once packages/eval/eval-cli/tsconfig.tests.json
 *  lands and the 6 specs resolve to a real program. KNOW-RED -> GREEN. */
const EVAL_CLI_PENDING_FIX: readonly string[] = [
  'packages/eval/eval-cli/tests/cli-llm-config.spec.ts',
  'packages/eval/eval-cli/tests/compare.spec.ts',
  'packages/eval/eval-cli/tests/harness-responder.spec.ts',
  'packages/eval/eval-cli/tests/main.spec.ts',
  'packages/eval/eval-cli/tests/report.spec.ts',
  'packages/eval/eval-cli/tests/scope-id.spec.ts',
]

/** Convert the glob subset used by STRICT_OVERRIDE_GLOBS to a RegExp. (minimatch/
 *  picomatch are NOT directly resolvable — pnpm-strict, transitive-only — so a
 *  focused matcher suffices for these 7 forms; swap to minimatch as a devDep if
 *  the globs ever gain brace-lists/negation/?) */
function strictOverrideGlobToRegex(glob: string): RegExp {
  let s = glob.replace(/[.+^${}()|[\]\\]/g, '\\$&')
  s = s.replace(/\*\*/g, '\u0000')          // placeholder for **
  s = s.replace(/\*/g, '[^/]+')             // single * = one path segment
  s = s.replace(/\u0000\//g, '([^/]+/)*')   // **/ = zero+ segments
  s = s.replace(/\u0000/g, '.*')            // leftover ** (none here)
  s = s.replace(/\{ts,tsx\}/, '(ts|tsx)')    // brace expansion
  return new RegExp('^' + s + '$')
}
const STRICT_OVERRIDE_REGEXES = STRICT_OVERRIDE_GLOBS.map(strictOverrideGlobToRegex)

/** UM-LINT-B durable fence: one OXC_LOG=debug pass, harvest Unmatched file: lines,
 *  fail if any (minus the eval-cli allowlist) match a strict-override glob. */
function assertNoStrictOverrideUnmatched(invocation: OxlintInvocation): void {
  const tmp = mkdtempSync(join(tmpdir(), 'oxlint-unmatched-'))
  try {
    const debugFd = openSync(join(tmp, 'debug.log'), 'w')
    const result = spawnSync(process.execPath, [oxlintCli, ...invocation.args], {
      env: { ...invocation.env, OXC_LOG: 'debug' },
      stdio: ['ignore', 'ignore', debugFd],
    })
    if (result.error !== undefined) throw result.error
    // The debug pass may exit non-zero if real lint errors exist; the program-coverage
    // assertion is independent of lint status, so parse the log regardless.
    const log = readFileSync(join(tmp, 'debug.log'), 'utf8')
    const unmatched: string[] = []
    for (const line of log.split('\n')) {
      const m = line.match(/Unmatched file:\s*(.+)/)
      if (m && m[1] !== undefined) unmatched.push(m[1].trim())
    }
    const violators = unmatched
      .map(p => relative(REPOSITORY_ROOT, p))
      .filter(p => !EVAL_CLI_PENDING_FIX.includes(p)
        && STRICT_OVERRIDE_REGEXES.some(re => re.test(p)))
    if (violators.length > 0) {
      process.stderr.write(
        `run-oxlint: ${violators.length} file(s) matching the strict type-aware override globs fell into tsgolint's inferred program (silent type-aware under-check). Add a real tsconfig owner for:\n`
          + violators.map(p => `  ${p}`).join('\n') + '\n',
      )
      process.exitCode = 1
    }
  } finally {
    rmSync(tmp, { recursive: true, force: true })
  }
}
```

